INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 9, 'theory', 'Quiz: raw, qcow2, layers, and snapshots');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 9, 0, 'How does raw differ from qcow2?', '["raw is disk bytes in a row with no metadata: fast, but no snapshots; qcow2 supports snapshots, layers, and allocation on demand", "raw supports snapshots, while qcow2 does not", "They are the same", "raw is always compressed"]', 0, 'raw is put on a logical volume for speed; qcow2 is chosen for flexibility.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 9, 1, 'How does qcow2 find a cluster by a guest address?', '["By linear search through the file", "Through a hash table", "Through two tables: L1 points to L2 tables, and those hold the cluster offsets in the file", "Directly by sector number"]', 2, 'As long as the guest hasn''t written to a cluster, the cluster itself doesn''t exist in the file.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 9, 2, 'What happens when you write to a layer on top of a backing image?', '["The backing image is modified", "The cluster is copied into the top layer, and the base stays untouched", "The write is discarded", "The layer is deleted"]', 1, 'This is copy-on-write: hundreds of machines can start from one base, and each stores only its own changes.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 9, 3, 'What is needed for a consistent snapshot of a running machine''s disk?', '["Shut down the host", "Nothing: every snapshot is consistent", "Increase the cluster size", "Use the guest agent to flush caches and freeze writes, take the snapshot, and thaw"]', 3, 'Otherwise the snapshot is only crash-consistent, as after a sudden power loss.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 9, 4, 'Why does a long layer chain slow down reads?', '["A read from a deep layer passes through all the layers above it, and each has to be checked", "The cluster size grows", "Data is encrypted at every layer", "The host overheats"]', 0, 'That''s why layers are merged periodically (commit) or the chain is flattened into a single image.');
